  5→function withDefault(value, extractor) {
  6→  if (!value) {
  7→    return null;
  8→  }
  9→
 10→  try {
 11→    return extractor(value);
 12→  } catch (error) {
 13→    console.warn(`camoufox: failed to initialize Playwright shim (${error.message || error})`);
 14→    return null;
 15→  }
 16→}
 17→
 18→function resolvePlaywrightApi(candidate) {
 19→  if (!candidate) {
 20→    return null;
 21→  }
 22→
 23→  if (candidate.firefox) {
 24→    return candidate;
 25→  }
 26→
 27→  if (candidate.default) {
 28→    const resolved = resolvePlaywrightApi(candidate.default);
 29→    if (resolved) {
 30→      return resolved;
 31→    }
 32→  }
 33→
 34→  if (typeof candidate.createInProcessPlaywright === 'function') {
 35→    const resolved = withDefault(candidate, (mod) => mod.createInProcessPlaywright());
 36→    if (resolved) {
 37→      return resolved;
 38→    }
 39→  }
 40→
 41→  if (typeof candidate.createPlaywright === 'function') {
 42→    const resolved = withDefault(candidate, (mod) => mod.createPlaywright({ sdkLanguage: process.env.PW_LANG_NAME || 'javascript' }));
 43→    if (resolved && resolved.firefox) {
 44→      return resolved;
 45→    }
 46→  }
 47→
 48→  if (candidate.playwright) {
 49→    return resolvePlaywrightApi(candidate.playwright);
 50→  }
 51→
 52→  return null;
 53→}
 54→
 55→function loadPlaywright() {
 56→  const override = process.env.CAMOUFOX_PLAYWRIGHT_JS_REQUIRE;
 57→  if (override) {
 58→    // eslint-disable-next-line global-require, import/no-dynamic-require
 59→    return require(override);
 60→  }
 61→
 62→  try {
 63→    // eslint-disable-next-line global-require, import/no-dynamic-require
 64→    return require('playwright');
 65→  } catch (error) {
 66→    // fall through
 67→  }
 68→
 69→  const driverDir = process.env.CAMOUFOX_PLAYWRIGHT_DRIVER_DIR;
 70→  if (driverDir) {
 71→    try {
 72→      // eslint-disable-next-line global-require, import/no-dynamic-require
 73→      return require(path.join(driverDir, 'package'));
 74→    } catch (error) {
 75→      // fall through
 76→    }
 77→  }
 78→
 79→  console.error('Unable to require Playwright. Install the `playwright` npm package or set CAMOUFOX_PLAYWRIGHT_JS_REQUIRE.');
 80→  process.exit(1);
 81→}
