 83→function decodePayload(line) {
 84→  const trimmed = (line || '').trim();
 85→  if (!trimmed) {
 86→    return null;
 87→  }
 88→  const buffer = Buffer.from(trimmed, 'base64');
 89→  return JSON.parse(buffer.toString());
 90→}
 91→
 92→function encodePayload(message) {
 93→  const json = JSON.stringify(message);
 94→  return Buffer.from(json).toString('base64');
 95→}
 96→
 97→function writeMessage(message) {
 98→  process.stdout.write(`${encodePayload(message)}\n`);
 99→}
100→
101→function coercePageFunction(expression) {
102→  const trimmed = (expression || '').trim();
103→  if (!trimmed) {
104→    return null;
105→  }
106→  try {
107→    const evaluated = eval(`(${trimmed})`); // eslint-disable-line no-eval
108→    if (typeof evaluated === 'function') {
109→      return evaluated;
110→    }
111→  } catch (error) {
112→    // fall through – treat expression as plain script
113→  }
114→  return null;
115→}
