117→async function waitForNetworkIdle(page, timeout) {
118→  try {
119→    await page.waitForLoadState('networkidle', { timeout });
120→  } catch (error) {
121→    console.warn(`camoufox: waitForLoadState(networkidle) warning: ${error.message || error}`);
122→  }
123→}
