  5→namespace {
  6→
  7→VALUE pkgman_module() {
  8→  ID camoufox_id = rb_intern("Camoufox");
  9→  if (!rb_const_defined(rb_cObject, camoufox_id)) {
 10→    return Qnil;
 11→  }
 12→
 13→  VALUE camoufox_mod = rb_const_get(rb_cObject, camoufox_id);
 14→  ID pkgman_id = rb_intern("Pkgman");
 15→  if (!rb_const_defined(camoufox_mod, pkgman_id)) {
 16→    return Qnil;
 17→  }
 18→
 19→  return rb_const_get(camoufox_mod, pkgman_id);
 20→}
 21→
 22→VALUE pkgman_default_executable() {
 23→  VALUE pkgman = pkgman_module();
 24→  if (NIL_P(pkgman)) {
 25→    return Qnil;
 26→  }
 27→
 28→  return rb_funcall(pkgman, rb_intern("executable_path"), 0);
 29→}
 30→
 31→VALUE fetch_executable_path(VALUE rb_options) {
 32→  ID executable_id = rb_intern("executable_path");
 33→  VALUE executable_key = ID2SYM(executable_id);
 34→  VALUE explicit_value = rb_hash_lookup(rb_options, executable_key);
 35→
 36→  if (!NIL_P(explicit_value)) {
 37→    return explicit_value;
 38→  }
 39→
 40→  const char* env_value = std::getenv("CAMOUFOX_EXECUTABLE_PATH");
 41→  if (env_value && env_value[0] != '\0') {
 42→    return rb_str_new_cstr(env_value);
 43→  }
 44→
 45→  VALUE pkgman_path = pkgman_default_executable();
 46→  if (!NIL_P(pkgman_path)) {
 47→    return pkgman_path;
 48→  }
 49→
 50→  return Qnil;
 51→}
 52→
 53→VALUE build_stub_launch_options(VALUE rb_options) {
 54→  Check_Type(rb_options, T_HASH);
 55→  VALUE result = rb_hash_new();
 56→
 57→  VALUE executable_key = ID2SYM(rb_intern("executable_path"));
 58→  VALUE executable_path = fetch_executable_path(rb_options);
 59→  rb_hash_aset(result, executable_key, executable_path);
 60→
 61→  VALUE args = rb_ary_new();
 62→  rb_hash_aset(result, ID2SYM(rb_intern("args")), args);
 63→
 64→  VALUE env = rb_hash_new();
 65→  rb_hash_aset(env, rb_str_new_cstr("CAMOU_CONFIG_1"), rb_str_new_cstr("{}"));
 66→  rb_hash_aset(result, ID2SYM(rb_intern("env")), env);
 67→
 68→  ID headless_id = rb_intern("headless");
 69→  VALUE headless_key = ID2SYM(headless_id);
 70→  VALUE headless_value = rb_hash_lookup(rb_options, headless_key);
 71→
 72→  if (NIL_P(headless_value)) {
 73→    headless_value = Qfalse;
 74→  } else {
 75→    headless_value = RTEST(headless_value) ? Qtrue : Qfalse;
 76→  }
 77→
 78→  rb_hash_aset(result, headless_key, headless_value);
 79→
 80→  ID user_data_dir_id = rb_intern("user_data_dir");
 81→  VALUE user_data_dir_key = ID2SYM(user_data_dir_id);
 82→  VALUE user_data_dir_value = rb_hash_lookup(rb_options, user_data_dir_key);
 83→  if (!NIL_P(user_data_dir_value)) {
 84→    rb_hash_aset(result, user_data_dir_key, user_data_dir_value);
 85→  }
 86→
 87→  return result;
 88→}
 89→
 90→VALUE build_cli_response(const char* command) {
 91→  VALUE pkgman = pkgman_module();
 92→
 93→  if (strcmp(command, "path") == 0) {
 94→    if (!NIL_P(pkgman)) {
 95→      VALUE dir = rb_funcall(pkgman, rb_intern("install_dir"), 0);
 96→      if (!NIL_P(dir)) {
 97→        VALUE result = rb_str_dup(dir);
 98→        rb_str_cat_cstr(result, "\n");
 99→        return result;
100→      }
101→    }
102→    return rb_str_new_cstr("(not configured)\n");
103→  }
104→  if (strcmp(command, "version") == 0) {
105→    if (!NIL_P(pkgman)) {
106→      VALUE ver = rb_funcall(pkgman, rb_intern("version_string"), 0);
107→      if (!NIL_P(ver)) {
108→        VALUE result = rb_str_new_cstr("Camoufox ");
109→        rb_str_append(result, ver);
110→        rb_str_cat_cstr(result, "\n");
111→        return result;
112→      }
113→    }
114→    return rb_str_new_cstr("Camoufox not installed\n");
115→  }
116→  if (strcmp(command, "fetch") == 0) {
117→    if (!NIL_P(pkgman)) {
118→      rb_funcall(pkgman, rb_intern("install"), 0);
119→      return rb_str_new_cstr("Fetch complete.\n");
120→    }
121→    return rb_str_new_cstr("Pkgman not available.\n");
122→  }
123→  if (strcmp(command, "remove") == 0) {
124→    if (!NIL_P(pkgman)) {
125→      rb_funcall(pkgman, rb_intern("remove"), 0);
126→      return rb_str_new_cstr("Remove complete.\n");
127→    }
128→    return rb_str_new_cstr("Pkgman not available.\n");
129→  }
130→  return rb_str_new_cstr("Unknown command.\n");
131→}
132→
133→VALUE native_launch_options(VALUE self, VALUE rb_options) {
134→  return build_stub_launch_options(rb_options);
135→}
136→
137→VALUE native_cli(int argc, VALUE* argv, VALUE self) {
138→  if (argc < 1) {
139→    rb_raise(rb_eArgError, "command required");
140→  }
141→  VALUE command_val = argv[0];
142→  Check_Type(command_val, T_STRING);
143→  const char* command = StringValueCStr(command_val);
144→  return build_cli_response(command);
145→}
146→
147→} // namespace
148→
149→extern "C" void Init_camoufox_native() {
150→  VALUE camoufox_module = rb_define_module("CamoufoxNative");
151→  rb_define_module_function(camoufox_module, "launch_options", RUBY_METHOD_FUNC(native_launch_options), 1);
152→  rb_define_module_function(camoufox_module, "run_cli", RUBY_METHOD_FUNC(native_cli), -1);
153→}
