 1→// Adapted from the Camoufox Python implementation
 2→// Launches the Playwright browser server by invoking the undocumented launchServer API.
 3→
 4→const path = require('path');
 5→const fs = require('fs');
 6→
 7→function resolveBrowserServerImpl() {
 8→  const cwd = process.cwd();
 9→  const candidate = path.join(cwd, 'lib', 'browserServerImpl.js');
10→  try {
11→    // eslint-disable-next-line global-require, import/no-dynamic-require
12→    return require(candidate);
13→  } catch (error) {
14→    console.error('Unable to load Playwright browserServerImpl.js from', candidate);
15→    console.error('Set CAMOUFOX_PLAYWRIGHT_DRIVER_DIR to the Playwright driver directory.');
16→    process.exit(1);
17→  }
18→}
19→
20→const { BrowserServerLauncherImpl } = resolveBrowserServerImpl();
21→
22→function collectData() {
23→  return new Promise((resolve) => {
24→    let data = '';
25→    process.stdin.setEncoding('utf8');
26→
27→    process.stdin.on('data', (chunk) => {
28→      data += chunk;
29→    });
30→
31→    process.stdin.on('end', () => {
32→      const buffer = Buffer.from(data, 'base64');
33→      resolve(JSON.parse(buffer.toString()));
34→    });
35→  });
36→}
37→
38→collectData()
39→  .then((options) => {
40→    if (options.executablePath && !fs.existsSync(options.executablePath)) {
41→      console.warn(`camoufox: executable ${options.executablePath} not found, falling back to Playwright default`);
42→      delete options.executablePath;
43→    }
44→
45→    console.time('Server launched');
46→    console.info('Launching server...');
47→
48→    const server = new BrowserServerLauncherImpl('firefox');
49→
50→    server
51→      .launchServer(options)
52→      .then((browserServer) => {
53→        console.timeEnd('Server launched');
54→        console.log('Websocket endpoint:\x1b[93m', browserServer.wsEndpoint(), '\x1b[0m');
55→        process.stdin.resume();
56→      })
57→      .catch((error) => {
58→        console.error('Error launching server:', error.message);
59→        process.exit(1);
60→      });
61→  })
62→  .catch((error) => {
63→    console.error('Error collecting data:', error.message);
64→    process.exit(1);
65→  });
