#include <ruby.h>
#include <cstring>
#include <cstdlib>

namespace {

VALUE pkgman_module() {
  ID camoufox_id = rb_intern("Camoufox");
  if (!rb_const_defined(rb_cObject, camoufox_id)) {
    return Qnil;
  }

  VALUE camoufox_mod = rb_const_get(rb_cObject, camoufox_id);
  ID pkgman_id = rb_intern("Pkgman");
  if (!rb_const_defined(camoufox_mod, pkgman_id)) {
    return Qnil;
  }

  return rb_const_get(camoufox_mod, pkgman_id);
}

VALUE pkgman_default_executable() {
  VALUE pkgman = pkgman_module();
  if (NIL_P(pkgman)) {
    return Qnil;
  }

  return rb_funcall(pkgman, rb_intern("executable_path"), 0);
}

VALUE fetch_executable_path(VALUE rb_options) {
  Check_Type(rb_options, T_HASH);

  ID executable_id = rb_intern("executable_path");
  VALUE executable_key = ID2SYM(executable_id);
  VALUE explicit_value = rb_hash_lookup(rb_options, executable_key);

  if (!NIL_P(explicit_value)) {
    return explicit_value;
  }

  const char* env_value = std::getenv("CAMOUFOX_EXECUTABLE_PATH");
  if (env_value && env_value[0] != '\0') {
    return rb_str_new_cstr(env_value);
  }

  VALUE pkgman_path = pkgman_default_executable();
  if (!NIL_P(pkgman_path)) {
    return pkgman_path;
  }

  return Qnil;
}

VALUE build_cli_response(const char* command) {
  VALUE pkgman = pkgman_module();

  if (strcmp(command, "path") == 0) {
    if (!NIL_P(pkgman)) {
      VALUE dir = rb_funcall(pkgman, rb_intern("install_dir"), 0);
      if (!NIL_P(dir)) {
        VALUE result = rb_str_dup(dir);
        rb_str_cat_cstr(result, "\n");
        return result;
      }
    }
    return rb_str_new_cstr("(not configured)\n");
  }
  if (strcmp(command, "version") == 0) {
    if (!NIL_P(pkgman)) {
      VALUE ver = rb_funcall(pkgman, rb_intern("version_string"), 0);
      if (!NIL_P(ver)) {
        VALUE result = rb_str_new_cstr("Camoufox ");
        rb_str_append(result, ver);
        rb_str_cat_cstr(result, "\n");
        return result;
      }
    }
    return rb_str_new_cstr("Camoufox not installed\n");
  }
  if (strcmp(command, "fetch") == 0) {
    if (!NIL_P(pkgman)) {
      rb_funcall(pkgman, rb_intern("install"), 0);
      return rb_str_new_cstr("Fetch complete.\n");
    }
    return rb_str_new_cstr("Pkgman not available.\n");
  }
  if (strcmp(command, "remove") == 0) {
    if (!NIL_P(pkgman)) {
      rb_funcall(pkgman, rb_intern("remove"), 0);
      return rb_str_new_cstr("Remove complete.\n");
    }
    return rb_str_new_cstr("Pkgman not available.\n");
  }
  return rb_str_new_cstr("Unknown command.\n");
}

VALUE native_executable_path(VALUE self, VALUE rb_options) {
  return fetch_executable_path(rb_options);
}

VALUE native_cli(int argc, VALUE* argv, VALUE self) {
  if (argc < 1) {
    rb_raise(rb_eArgError, "command required");
  }
  VALUE command_val = argv[0];
  Check_Type(command_val, T_STRING);
  const char* command = StringValueCStr(command_val);
  return build_cli_response(command);
}

} // namespace

extern "C" void Init_camoufox_native() {
  VALUE camoufox_module = rb_define_module("CamoufoxNative");
  rb_define_module_function(camoufox_module, "executable_path", RUBY_METHOD_FUNC(native_executable_path), 1);
  rb_define_module_function(camoufox_module, "run_cli", RUBY_METHOD_FUNC(native_cli), -1);
}

# frozen_string_literal: true

module Camoufox
  module MCP
    module Tools
      class Launch < ::MCP::Tool
        tool_name "camoufox_launch"
        description "Launch a stealth Camoufox browser session with anti-detection features"

        input_schema(
          properties: {
            headless: {
              type: "boolean",
              description: "Run the browser without a visible window",
            },
            user_data_dir: {
              type: "string",
              description: "Path to a user data directory for persistent browser profiles",
            },
            proxy_server: {
              type: "string",
              description: "Proxy server URL (e.g. http://proxy:8080 or socks5://proxy:1080)",
            },
            proxy_username: {
              type: "string",
              description: "Proxy authentication username",
            },
            proxy_password: {
              type: "string",
              description: "Proxy authentication password",
            },
            block_images: {
              type: "boolean",
              description: "Block all images from loading",
            },
            block_webrtc: {
              type: "boolean",
              description: "Disable WebRTC entirely to prevent IP leaks",
            },
            block_webgl: {
              type: "boolean",
              description: "Disable WebGL to prevent GPU fingerprinting",
            },
            locale: {
              type: "string",
              description: "Browser locale (e.g. en-US, fr-FR)",
            },
            os: {
              type: "string",
              description: "Target OS for fingerprint (macos, windows, linux)",
            },
            geoip: {
              type: "string",
              description: "IP address for geolocation matching, or 'auto' to detect",
            },
            enable_cache: {
              type: "boolean",
              description: "Enable browser disk and memory cache",
            },
            disable_coop: {
              type: "boolean",
              description: "Disable Cross-Origin-Opener-Policy",
            },
          },
        )

        class << self
          def call(server_context:, **kwargs)
            session = server_context[:session]
            opts = {}
            opts[:headless] = kwargs[:headless] unless kwargs[:headless].nil?
            opts[:user_data_dir] = kwargs[:user_data_dir] if kwargs[:user_data_dir]
            opts[:block_images] = kwargs[:block_images] if kwargs[:block_images]
            opts[:block_webrtc] = kwargs[:block_webrtc] if kwargs[:block_webrtc]
            opts[:block_webgl] = kwargs[:block_webgl] if kwargs[:block_webgl]
            opts[:locale] = kwargs[:locale] if kwargs[:locale]
            opts[:enable_cache] = kwargs[:enable_cache] if kwargs[:enable_cache]
            opts[:disable_coop] = kwargs[:disable_coop] if kwargs[:disable_coop]
            opts[:os] = kwargs[:os].to_sym if kwargs[:os]

            if kwargs[:geoip]
              opts[:geoip] = kwargs[:geoip] == "auto" ? true : kwargs[:geoip]
            end

            if kwargs[:proxy_server]
              proxy = { server: kwargs[:proxy_server] }
              proxy[:username] = kwargs[:proxy_username] if kwargs[:proxy_username]
              proxy[:password] = kwargs[:proxy_password] if kwargs[:proxy_password]
              opts[:proxy] = proxy
            end

            session.launch(**opts)

            features = []
            features << "headless" if opts[:headless]
            features << "proxy" if opts[:proxy]
            features << "webrtc blocked" if opts[:block_webrtc]
            features << "images blocked" if opts[:block_images]
            features << "webgl blocked" if opts[:block_webgl]
            features << "locale=#{opts[:locale]}" if opts[:locale]
            features << "os=#{opts[:os]}" if opts[:os]

            detail = features.empty? ? "" : " (#{features.join(', ')})"

            ::MCP::Tool::Response.new([{
              type: "text",
              text: "Browser launched successfully#{detail}.",
            }])
          end
        end
      end
    end
  end
end

